package com.tremu.app;

/** The "Ajouter des jeux" page served by LibraryServer (plain HTML, no external resources), in the
 *  language chosen in the headset. */
final class LibraryPage {
    private LibraryPage() {}

    static String html() {
        return "<!doctype html><html lang=" + Lang.code() + "><head><meta charset=utf-8>"
            + "<meta name=viewport content='width=device-width,initial-scale=1'><title>Tremu - " + Lang.h("Mes jeux") + "</title><style>"
            + ":root{--bg:#0b1220;--panel:#121a2b;--line:#22304a;--text:#e2e8f0;--dim:#94a3b8;--cyan:#22d3ee;--red:#ff6b6b;--ok:#4ade80}"
            + "*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.45 system-ui,sans-serif}"
            + "main{max-width:900px;margin:0 auto;padding:24px 16px}h1{margin:0 0 4px;font-size:28px}h1 b{color:var(--cyan)}h1 i{color:var(--red);font-style:normal}"
            + "p{color:var(--dim);margin:0 0 20px}section{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;margin-bottom:16px}"
            + "h2{font-size:17px;margin:0 0 12px;display:flex;justify-content:space-between;gap:8px}h2 small{color:var(--dim);font-weight:400}"
            + "#drop{border:2px dashed var(--line);border-radius:12px;padding:34px 12px;text-align:center;color:var(--dim);cursor:pointer}"
            + "#drop.over{border-color:var(--cyan);color:var(--text)}input,select,button{font:inherit;border-radius:10px;border:1px solid var(--line);background:#0e1626;color:var(--text);padding:10px 12px}"
            + "button{background:var(--cyan);color:#06222a;border:0;font-weight:600;cursor:pointer}.row{display:flex;gap:8px;flex-wrap:wrap}.row input{flex:1;min-width:200px}"
            + "ul{list-style:none;margin:0;padding:0}li{padding:6px 0;border-bottom:1px solid var(--line);font-size:14px;overflow-wrap:anywhere}"
            + ".ok{color:var(--ok)}.bad{color:var(--red)}"
            + ".tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}.tabs button{background:#0e1626;color:var(--text);border:1px solid var(--line)}"
            + ".tabs button.on{background:var(--cyan);color:#06222a}"
            + ".file{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}"
            + ".file img,.file .ph{width:42px;height:56px;object-fit:cover;border-radius:6px;background:#0e1626;flex:none}"
            + ".file .name{flex:1;min-width:0;overflow-wrap:anywhere;font-size:14px}.file .name small{display:block;color:var(--dim)}"
            + ".file .acts{display:flex;gap:4px;flex-wrap:wrap}.file .acts button{padding:6px 9px;font-size:13px;background:#0e1626;color:var(--text);border:1px solid var(--line)}"
            + ".file .acts button.del{color:var(--red)}.bar{height:8px;background:#0e1626;border-radius:4px;overflow:hidden;margin-top:6px}.bar div{height:100%;background:var(--cyan)}"
            + "#gate{position:fixed;inset:0;background:var(--bg);display:flex;align-items:center;justify-content:center;z-index:2}#gate div{text-align:center}"
            + "#gate input{font-size:28px;width:140px;text-align:center;letter-spacing:6px}</style></head><body>"
            + "<div id=gate><div><h1><b>Tr</b><i>emu</i></h1><p>" + Lang.h("Entre le code à 4 chiffres affiché dans le casque") + "</p>"
            + "<input id=code inputmode=numeric maxlength=4 autofocus></div></div>"
            + "<main><h1><b>Tr</b><i>emu</i> — " + Lang.h("Mes jeux") + "</h1><p id=link class=bad style='display:none'></p><p>" + Lang.h("Les fichiers vont directement dans le casque et apparaissent dans le carrousel. Arcade : .zip FBNeo. NES : .nes. SNES : .sfc/.smc. PlayStation : .cue+.bin, .chd ou .pbp (un .zip de jeu PlayStation est décompressé automatiquement).") + "</p>"
            + "<section><h2>" + Lang.h("Ajouter depuis cet appareil") + "</h2><div id=drop>" + Lang.h("Glisse ici tes ROM, BIOS ou affiches") + "<br>" + Lang.h("ou clique pour choisir") + "</div>"
            + "<input id=files type=file multiple hidden><div class=row style='margin-top:10px'><select id=dir><option value=auto>" + Lang.h("Rangement automatique") + "</option>"
            + "<option>Roms</option><option>bios</option><option>Banner</option></select></div></section>"
            + "<section><h2>" + Lang.h("Jeux Wii U : mises à jour et DLC") + "</h2><ul id=wiiu></ul>"
            + "<div class=row><button id=wiiuadd>" + Lang.h("Ajouter un dossier de jeu, de mise à jour ou de DLC") + "</button></div>"
            + "<input id=wiiufolder type=file webkitdirectory hidden></section>"
            + "<section><h2>" + Lang.h("Télécharger un lien directement dans le casque") + "</h2>"
            + "<p style='margin-bottom:10px'>" + Lang.h("Colle le lien direct du fichier : c'est le casque qui le télécharge, pas cet appareil. Les programmes et les pages web déguisées sont refusés.") + "</p>"
            + "<div class=row><input id=url placeholder='https://...'><button id=go>" + Lang.h("Télécharger") + "</button></div></section>"
            + "<section><h2>" + Lang.h("Activité") + "</h2><ul id=jobs></ul><ul id=log></ul></section>"
            + "<section><h2>" + Lang.h("Fichiers du casque") + " <small id=space></small></h2><div class=bar><div id=used></div></div><br>"
            + "<div class=tabs id=tabs></div><div id=list></div></section></main><script>"
            + "let code=localStorage.getItem('tremucode')||'',tab='Roms',data=null;const $=id=>document.getElementById(id);"
            + "const FOLDERS=['Roms','bios','Banner','Sauvegardes'];const LABEL={Sauvegardes:" + Lang.js("Sauvegardes") + "};"
            + "const size=b=>b>=1073741824?(b/1073741824).toFixed(1)+' '+" + Lang.js("Go") + ":b>=1048576?(b/1048576).toFixed(1)+' '+" + Lang.js("Mo") + ":Math.max(1,Math.round(b/1024))+' '+" + Lang.js("Ko") + ";"
            + "const q=o=>Object.entries(o).map(([k,v])=>k+'='+encodeURIComponent(v)).join('&');"
            + "function note(t,ok){const li=document.createElement('li');li.textContent=t;li.className=ok?'ok':'bad';$('log').prepend(li)}"
            + "async function api(path,opts){opts=opts||{};opts.headers=Object.assign({'X-Code':code},opts.headers||{});"
            + "const r=await fetch(path,opts);if(r.status==403){localStorage.removeItem('tremucode');$('gate').style.display='flex';throw new Error('code')}return r.json()}"
            + "async function act(path,params){try{const r=await api(path+'?'+q(params),{method:'POST'});note(r.message,r.ok)}catch(e){}refresh()}"
            + "function stem(n){return n.replace(/\\.[^.]*$/,'').toLowerCase()}"
            + "function render(){if(!data)return;const tabs=$('tabs');tabs.innerHTML='';"
            + "for(const f of FOLDERS){const b=document.createElement('button');b.textContent=(LABEL[f]||f)+' ('+data.folders[f].length+')';"
            + "b.className=f==tab?'on':'';b.onclick=()=>{tab=f;render()};tabs.append(b)}"
            + "const posters={};for(const p of data.folders.Banner)posters[stem(p.n)]=p.n;"
            + "const list=$('list');list.innerHTML='';const files=data.folders[tab];"
            + "if(!files.length){list.innerHTML='<p>'+" + Lang.js("Aucun fichier.") + "+'</p>';return}"
            + "for(const f of files){const row=document.createElement('div');row.className='file';"
            + "let pic=tab=='Banner'?f.n:tab=='Roms'?posters[stem(f.n)]:null;"
            + "if(pic){const img=document.createElement('img');img.loading='lazy';img.src='/download?'+q({dir:'Banner',name:pic,inline:1,k:code});row.append(img)}"
            + "else if(tab=='Roms'){const ph=document.createElement('div');ph.className='ph';ph.title=" + Lang.js("Pas d'affiche") + ";row.append(ph)}"
            + "const name=document.createElement('div');name.className='name';name.textContent=f.n;"
            + "const s=document.createElement('small');s.textContent=size(f.s)+(tab=='Roms'&&!pic?'  \\u00b7 '+" + Lang.js("pas d'affiche") + ":'');name.append(s);row.append(name);"
            + "const acts=document.createElement('div');acts.className='acts';"
            + "const btn=(label,title,fn,cls)=>{const b=document.createElement('button');b.textContent=label;b.title=title;if(cls)b.className=cls;b.onclick=fn;acts.append(b)};"
            + "btn('\\u2b07'," + Lang.js("Télécharger sur cet appareil") + ",()=>{location.href='/download?'+q({dir:tab,name:f.n,k:code})});"
            + "if(tab!='Sauvegardes'){btn('\\u270e'," + Lang.js("Renommer") + ",()=>{const to=prompt(" + Lang.js("Nouveau nom") + ",f.n);if(to&&to!=f.n)act('/rename',{dir:tab,name:f.n,to:to})});"
            + "const sel=document.createElement('select');sel.title=" + Lang.js("Déplacer vers") + ";sel.innerHTML='<option value=\"\">'+" + Lang.js("Déplacer…") + "+'</option>'+"
            + "['Roms','bios','Banner'].filter(d=>d!=tab).map(d=>'<option>'+d+'</option>').join('');"
            + "sel.style.padding='6px';sel.onchange=()=>{if(sel.value)act('/rename',{dir:tab,name:f.n,todir:sel.value})};acts.append(sel)}"
            + "btn('\\u{1F5D1}'," + Lang.js("Supprimer") + ",()=>{if(confirm(" + Lang.js("Supprimer %s du casque ?") + ".replace('%s',f.n)))act('/delete',{dir:tab,name:f.n})},'del');"
            + "row.append(acts);list.append(row)}}"
            + "async function refresh(){try{const d=await api('/list');const fresh=JSON.stringify(d.folders)!=JSON.stringify(data&&data.folders);data=d;"
            + "$('space').textContent=" + Lang.js("%s libres sur %s") + ".replace('%s',size(d.free)).replace('%s',size(d.total));$('used').style.width=Math.round(100-d.free*100/d.total)+'%';"
            + "const jobs=$('jobs');jobs.innerHTML='';"
            + "for(const j of d.jobs){const li=document.createElement('li');li.textContent=j;li.className=j[0]=='\\u2717'?'bad':j[0]=='\\u2713'?'ok':'';jobs.append(li)}"
            + "$('link').style.display='none';if(fresh)render()}catch(e){if(e.message!='code'){$('link').style.display='block';"
            + "$('link').textContent='\\u26A0 '+" + Lang.js("Le casque ne répond pas : Tremu doit être ouvert dans le casque (il peut être en veille) et sur le même Wi-Fi.") + "}}}"
            + "function send(f){return new Promise(res=>{const x=new XMLHttpRequest();"
            + "const rel=f.webkitRelativePath||'';x.open('PUT','/file?'+q(rel?{dir:'wiiu',sub:rel.split('/')[0],name:f.name}:{dir:$('dir').value,name:f.name}));x.setRequestHeader('X-Code',code);"
            + "const li=document.createElement('li');li.textContent=f.name+' : 0 %';$('log').prepend(li);"
            + "x.upload.onprogress=e=>{if(e.lengthComputable)li.textContent=f.name+' : '+Math.floor(e.loaded*100/e.total)+' %'};"
            + "x.onload=()=>{let r={ok:false,message:" + Lang.js("%s : erreur") + ".replace('%s',f.name)};try{r=JSON.parse(x.responseText)}catch(e){}"
            + "li.textContent=r.message;li.className=r.ok?'ok':'bad';refresh();res()};"
            + "x.onerror=()=>{li.textContent=" + Lang.js("%s : envoi impossible") + ".replace('%s',f.name);li.className='bad';res()};x.send(f)})}"
            + "async function sendAll(list){for(const f of list)await send(f);wiiu()}"
            + "async function wiiu(){try{const d=await api('/wiiu');const l=$('wiiu');l.innerHTML='';if(!d.games.length)l.textContent=" + Lang.js("Aucun jeu Wii U dans Download/Roms/wiiu") + ";"
            + "for(const g of d.games){const li=document.createElement('li');li.textContent=g.name+' \\u2014 '+g.status+' ';"
            + "const del=(label,path)=>{if(!path)return;const b=document.createElement('button');b.textContent=label;"
            + "b.onclick=async()=>{if(confirm(" + Lang.js("Supprimer %s du casque ?") + ".replace('%s',path.split('/').pop()))){await act('/wiiu/delete',{path});wiiu()}};li.append(b)};"
            + "del(" + Lang.js("Supprimer le jeu") + ",g.game);if(g.update!=g.game)del(" + Lang.js("Supprimer la mise à jour") + ",g.update);"
            + "if(g.dlc!=g.game&&g.dlc!=g.update)del(" + Lang.js("Supprimer le DLC") + ",g.dlc);l.append(li)}}catch(e){}}"
            + "$('wiiuadd').onclick=()=>$('wiiufolder').click();$('wiiufolder').onchange=e=>sendAll([...e.target.files]);wiiu();setInterval(wiiu,15000);"
            + "const drop=$('drop');drop.onclick=()=>$('files').click();$('files').onchange=e=>sendAll([...e.target.files]);"
            + "drop.ondragover=e=>{e.preventDefault();drop.classList.add('over')};drop.ondragleave=()=>drop.classList.remove('over');"
            + "drop.ondrop=e=>{e.preventDefault();drop.classList.remove('over');sendAll([...e.dataTransfer.files])};"
            + "$('go').onclick=async()=>{const u=$('url').value.trim();if(!u){note(" + Lang.js("Colle d'abord un lien") + ",false);return}"
            + "const b=$('go');b.disabled=true;b.textContent=" + Lang.js("Envoi…") + ";"
            + "try{const r=await api('/fetch?'+q({dir:$('dir').value,url:u}),{method:'POST'});"
            + "note(r.message+(r.ok?' \\u2014 '+" + Lang.js("suis la progression dans Activité") + ":''),r.ok);if(r.ok)$('url').value='';refresh()}"
            + "catch(e){note(" + Lang.js("Le casque ne répond pas : réessaie quand Tremu est ouvert") + ",false)}"
            + "b.disabled=false;b.textContent=" + Lang.js("Télécharger") + "};"
            + "$('code').oninput=async e=>{if(e.target.value.length==4){code=e.target.value;"
            + "try{await api('/list');localStorage.setItem('tremucode',code);$('gate').style.display='none';refresh()}catch(err){e.target.value=''}}};"
            + "if(code)api('/list').then(()=>{$('gate').style.display='none';refresh()}).catch(()=>{});"
            + "setInterval(refresh,2000)</script></body></html>";
    }
}
